// Nothing OS Color Scheme
private object StepCounterColors {
    val Void = Color(0xFF0A0A0A)
    val Surface0 = Color(0xFF111111)
    val Surface1 = Color(0xFF1A1A1A)
    val Surface2 = Color(0xFF222222)
    val Hairline = Color(0xFF2C2C2C)
    val NothingWhite = Color(0xFFFFFFFF)
    val OffWhite = Color(0xFFE8E8E8)
    val DimWhite = Color(0xFF8A8A8A)
    val FaintWhite = Color(0xFF3A3A3A)
    val GlyphRed = Color(0xFFFF3A3A)
    val PositiveGreen = Color(0xFF32E05A)
    val PositiveBlue = Color(0xFF00BCD4)
}

@Composable
fun StepCounterScreen(
    viewModel: StepCounterViewModel = viewModel(),
    onNavigateBack: () -> Unit
) {
    val state by viewModel.state.collectAsState()
    val snackbarHostState = remember { SnackbarHostState() }
    val scope = rememberCoroutineScope()

    LaunchedEffect(Unit) {
        viewModel.uiEvent.collect { event ->
            when (event) {
                is StepCounterUiEvent.ShowSnackbar -> {
                    scope.launch {
                        snackbarHostState.showSnackbar(event.message)
                    }
                }
                is StepCounterUiEvent.NavigateToHome -> onNavigateBack()
            }
        }
    }

    Scaffold(
        containerColor = StepCounterColors.Void,
        snackbarHost = { SnackbarHost(snackbarHostState) },
        topBar = {
            StepCounterAppBar(onNavigateBack = onNavigateBack)
        }
    ) { paddingValues ->
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
                .background(StepCounterColors.Void),
            contentPadding = PaddingValues(16.dp),
            verticalArrangement = Arrangement.spacedBy(20.dp)
        ) {
            // Daily Progress Circle
            item {
                DailyProgressCard(
                    stepsToday = state.stepsToday,
                    stepGoal = state.stepGoal,
                    percentageComplete = state.percentageComplete,
                    onRefresh = { viewModel.onEvent(StepCounterEvent.OnRefresh) }
                )
            }

            // Quick Stats Row
            item {
                QuickStatsRow(
                    caloriesBurned = state.caloriesBurned,
                    distanceCovered = state.distanceCovered,
                    avgDailySteps = state.avgDailySteps
                )
            }

            // Manual Entry Section
            if (!state.hasHealthConnectPermission) {
                item {
                    ManualStepEntryCard(
                        stepInputText = state.stepInputText,
                        isManualEntry = state.isManualEntry,
                        isLoading = state.isLoading,
                        onStepInputChanged = { viewModel.onEvent(StepCounterEvent.OnStepInputChanged(it)) },
                        onToggleManualEntry = { viewModel.onEvent(StepCounterEvent.OnToggleManualEntry(it)) },
                        onSubmit = { viewModel.onEvent(StepCounterEvent.OnManualStepsSubmit) }
                    )
                }
            }

            // Step Goal Adjustment
            item {
                StepGoalAdjustmentCard(
                    currentGoal = state.stepGoal,
                    onGoalChanged = { viewModel.onEvent(StepCounterEvent.OnStepGoalChanged(it)) }
                )
            }

            // Weekly Stats
            item {
                WeeklyStatsCard(weeklySteps = state.weeklySteps)
            }

            // Error State
            if (state.errorMessage != null) {
                item {
                    ErrorCard(message = state.errorMessage)
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun StepCounterAppBar(onNavigateBack: () -> Unit) {
    TopAppBar(
        title = {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Box(
                    modifier = Modifier
                        .width(2.dp)
                        .height(20.dp)
                        .background(StepCounterColors.GlyphRed)
                )
                Spacer(modifier = Modifier.width(10.dp))
                Text(
                    text = "STEPS",
                    color = StepCounterColors.NothingWhite,
                    fontWeight = FontWeight.Black,
                    fontSize = 16.sp,
                    letterSpacing = 3.sp,
                    fontFamily = FontFamily.Monospace
                )
            }
        },
        navigationIcon = {
            IconButton(onClick = onNavigateBack) {
                Icon(
                    imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                    contentDescription = "Back",
                    tint = StepCounterColors.NothingWhite
                )
            }
        },
        colors = TopAppBarDefaults.topAppBarColors(containerColor = StepCounterColors.Surface1),
