                    )
                    IconButton(
                        onClick = { onToggleManualEntry(!isManualEntry) },
                        modifier = Modifier.size(28.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Default.Edit,
                            contentDescription = "Edit",
                            tint = StepCounterColors.PositiveBlue,
                            modifier = Modifier.size(16.dp)
                        )
                    }
                }

                if (isManualEntry) {
                    Spacer(modifier = Modifier.height(12.dp))
                    TextField(
                        value = stepInputText,
                        onValueChange = onStepInputChanged,
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(StepCounterColors.Surface0, RoundedCornerShape(4.dp)),
                        placeholder = {
                            Text(
                                "Enter number of steps",
                                color = StepCounterColors.FaintWhite,
                                fontSize = 12.sp
                            )
                        },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                        colors = TextFieldDefaults.colors(
                            unfocusedContainerColor = StepCounterColors.Surface0,
                            focusedContainerColor = StepCounterColors.Surface0,
                            unfocusedTextColor = StepCounterColors.NothingWhite,
                            focusedTextColor = StepCounterColors.NothingWhite,
                            cursorColor = StepCounterColors.PositiveBlue
                        ),
                        textStyle = androidx.compose.ui.text.TextStyle(
                            fontSize = 14.sp,
                            fontFamily = FontFamily.Monospace
                        )
                    )

                    Spacer(modifier = Modifier.height(12.dp))

                    Button(
                        onClick = onSubmit,
                        modifier = Modifier.fillMaxWidth(),
                        colors = ButtonDefaults.buttonColors(
                            containerColor = StepCounterColors.PositiveBlue
                        ),
                        enabled = !isLoading && stepInputText.isNotBlank(),
                        shape = RoundedCornerShape(4.dp)
                    ) {
                        Text(
                            "RECORD STEPS",
                            color = StepCounterColors.Void,
                            fontWeight = FontWeight.Black,
                            letterSpacing = 1.sp,
                            fontFamily = FontFamily.Monospace,
                            fontSize = 11.sp
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun StepGoalAdjustmentCard(
    currentGoal: Long,
    onGoalChanged: (Long) -> Unit
) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .background(StepCounterColors.Surface0, RoundedCornerShape(8.dp))
            .padding(1.dp)
    ) {
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .background(StepCounterColors.Surface1, RoundedCornerShape(7.dp))
                .padding(16.dp)
        ) {
            Column(modifier = Modifier.fillMaxWidth()) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Box(
                        modifier = Modifier
                            .width(2.dp)
                            .height(16.dp)
                            .background(StepCounterColors.GlyphRed)
                    )
                    Spacer(modifier = Modifier.width(8.dp))
                    Text(
                        text = "DAILY GOAL",
                        color = StepCounterColors.NothingWhite,
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold,
                        letterSpacing = 2.sp,
                        fontFamily = FontFamily.Monospace
                    )
                }

                Spacer(modifier = Modifier.height(12.dp))

                Row(
                    modifier = Modifier
                        .fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    val goals = listOf(5000L, 7500L, 10000L, 12500L, 15000L)
                    goals.forEach { goal ->
                        GoalButton(
                            goal = goal,
                            isSelected = goal == currentGoal,
                            onClick = { onGoalChanged(goal) },
                            modifier = Modifier.weight(1f)
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun GoalButton(
    goal: Long,
    isSelected: Boolean,
    onClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    val bgColor by animateColorAsState(
        targetValue = if (isSelected) StepCounterColors.PositiveBlue else StepCounterColors.Surface0,
        animationSpec = tween(200)
    )
    val textColor by animateColorAsState(
        targetValue = if (isSelected) StepCounterColors.Void else StepCounterColors.DimWhite,
        animationSpec = tween(200)
    )

    Button(
        onClick = onClick,
        modifier = modifier,
        colors = ButtonDefaults.buttonColors(containerColor = bgColor),
        shape = RoundedCornerShape(4.dp)
    ) {
        Text(
            "${goal / 1000}K",
            color = textColor,
            fontSize = 11.sp,
            fontWeight = FontWeight.Bold,
            fontFamily = FontFamily.Monospace
        )
    }
}

@Composable
private fun WeeklyStatsCard(weeklySteps: Map<String, Long>) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .background(StepCounterColors.Surface0, RoundedCornerShape(8.dp))
            .padding(1.dp)
    ) {
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .background(StepCounterColors.Surface1, RoundedCornerShape(7.dp))
                .padding(16.dp)
        ) {
            Column(modifier = Modifier.fillMaxWidth()) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Box(
                        modifier = Modifier
                            .width(2.dp)
                            .height(16.dp)
                            .background(StepCounterColors.GlyphRed)
                    )
                    Spacer(modifier = Modifier.width(8.dp))
                    Text(
                        text = "THIS WEEK",
                        color = StepCounterColors.NothingWhite,
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold,
                        letterSpacing = 2.sp,
                        fontFamily = FontFamily.Monospace
                    )
                }

                Spacer(modifier = Modifier.height(16.dp))

                if (weeklySteps.isEmpty()) {
                    Text(
                        "No weekly data available",
                        color = StepCounterColors.DimWhite,
                        fontSize = 12.sp,
                        fontFamily = FontFamily.Monospace,
                        textAlign = TextAlign.Center,
                        modifier = Modifier.fillMaxWidth()
                    )
                } else {
                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        weeklySteps.forEach { (day, steps) ->
                            WeeklyStepRow(day = day, steps = steps)
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun WeeklyStepRow(day: String, steps: Long) {
    Row(
        modifier = Modifier
            .fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Text(
            text = day,
            color = StepCounterColors.DimWhite,
            fontSize = 11.sp,
            fontFamily = FontFamily.Monospace,
            fontWeight = FontWeight.Bold,
            modifier = Modifier.width(40.dp)
        )

        // Bar chart representation
        val maxSteps = 10000L
        val barWidth = (steps.toFloat() / maxSteps.toFloat()).coerceIn(0.01f, 1f)
        Box(
            modifier = Modifier
                .weight(1f)
                .height(20.dp)
                .background(StepCounterColors.Surface0, RoundedCornerShape(2.dp))
        ) {
            Box(
                modifier = Modifier
                    .fillMaxHeight()
                    .fillMaxWidth(barWidth)
                    .background(
                        if (steps >= 10000) StepCounterColors.PositiveGreen else StepCounterColors.PositiveBlue,
                        RoundedCornerShape(2.dp)
                    )
            )
        }

        Spacer(modifier = Modifier.width(8.dp))

        Text(
            text = steps.toString(),
            color = StepCounterColors.NothingWhite,
            fontSize = 11.sp,
            fontFamily = FontFamily.Monospace,
            fontWeight = FontWeight.Bold,
            modifier = Modifier.width(50.dp),
            textAlign = TextAlign.End
        )
    }
}

@Composable
private fun ErrorCard(message: String) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .background(StepCounterColors.Surface0, RoundedCornerShape(8.dp))
            .padding(1.dp)
    ) {
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .background(StepCounterColors.Surface1, RoundedCornerShape(7.dp))
                .padding(16.dp)
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                modifier = Modifier.fillMaxWidth()
            ) {
                Box(
                    modifier = Modifier
                        .size(6.dp)
                        .background(StepCounterColors.GlyphRed, CircleShape)
                )
                Spacer(modifier = Modifier.width(12.dp))
                Text(
                    text = message,
                    color = StepCounterColors.DimWhite,
                    fontSize = 12.sp,
                    fontFamily = FontFamily.Monospace
                )
            }
        }
    }
}
